import u0Json from './u0-workspace.stub.json' with { type: 'json' };
import type { GraphEdge, GraphPackage } from '../../../bridge/common/graph-state.type.ts';
import type { U0Canvas, U0PackageRecord, U0Workspace } from '../common/u0-workspace.type.ts';

/**
 * The U0 workspace (`~/.cache/tc-u0-fixture`) re-captured in VS Code on the U5 builders (U6c Task 3.1): measured package
 * and task sizes, box title widths, the shown tasks of each task view and the edge ids of each captured ELK request.
 * Generated by `~/.cache/tc-u6c-plan/stub-of-cap.mjs`; edit the generator, not the JSON.
 */
export const U0_WORKSPACE_STUB: U0Workspace = u0Json;

const packageOf = (record: U0PackageRecord): GraphPackage => {
  const { name, path } = record;
  const pkg: GraphPackage = { name, bareName: name, path, tags: [], taskCount: 0 };

  return pkg;
};

/** The 19 packages of the U0 workspace, at their workspace paths, in the host's order. */
export const U0_PACKAGES_STUB: GraphPackage[] = U0_WORKSPACE_STUB.packages.map(packageOf);

/** The 28 package edges of the U0 workspace, each source depending on its target, in the host's order. */
export const U0_EDGES_STUB: GraphEdge[] = U0_WORKSPACE_STUB.edges;

/** The webview canvas the capture fitted each view into: 1022 × 999. */
export const U0_CANVAS_STUB: U0Canvas = U0_WORKSPACE_STUB.canvas;
